        case .hedge: return hedge
        case .pathEdges: return pathEdges
        case .path: return path
        case .pond: return pond
        case .backTrees: return backTrees
        case .pines: return pines
        case .bridge: return bridge
        case .bushes: return bushes
        case .doorBush: return doorBush
        case .door: return door
